//! THE LAWS — compile-adjacent structural guards.
//!
//! Law I  — no boolean gates (decisions are `match`, not runtime `if/else` webs).
//! Law II — no HashMap/BTree in the cognition path. Hashing structured keys into
//!          flat buckets collapses relational geometry (see
//!          `docs/ANTI_FLATTENING_LAW.md`). Maps are permitted ONLY below the
//!          sovereignty boundary: the block store / temporal ledger
//!          (`core::chain`) and wire/gossip framing (`network`).
//! Law V  — no residual suppression (unknown structure passes through).
//!
//! The Anti-Flattening guard below is the enforceable form of Law II: it scans
//! the cognition trees (`src/core/` minus `chain/`, plus `src/transducer/`) and
//! refuses any real map import or typed usage. A violation is a structural
//! defect, not a style nit — it means a dimension is about to die in a bucket.

#[cfg(test)]
mod anti_flattening {
    use std::path::{Path, PathBuf};

    /// Trees that carry cognition — no maps allowed.
    const COGNITION_ROOTS: &[&str] = &["src/core", "src/transducer", "src/cognition.rs"];
    /// Below-boundary subtrees exempt per the sovereignty rule (I/O + storage).
    const EXEMPT: &[&str] = &["src/core/chain", "src/network"];
    /// The forbidden associative containers.
    const BANNED: &[&str] = &["HashMap", "BTreeMap", "HashSet", "BTreeSet"];

    fn manifest_dir() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
    }

    fn is_exempt(rel: &str) -> bool {
        EXEMPT.iter().any(|e| rel.starts_with(e))
    }

    fn collect_rs(dir: &Path, out: &mut Vec<PathBuf>) {
        let Ok(entries) = std::fs::read_dir(dir) else { return };
        for e in entries.flatten() {
            let p = e.path();
            if p.is_dir() {
                collect_rs(&p, out);
            } else if p.extension().is_some_and(|x| x == "rs") {
                out.push(p);
            }
        }
    }

    /// A line "mentions" a banned container as code (not in a comment). We strip
    /// a trailing line-comment and any full-line comment before scanning, so the
    /// doctrine may name the banned types in prose without tripping the guard.
    fn code_of(line: &str) -> &str {
        let t = line.trim_start();
        if t.starts_with("//") {
            return "";
        }
        match line.find("//") {
            Some(i) => &line[..i],
            None => line,
        }
    }

    #[test]
    fn law_ii_no_maps_in_cognition() {
        let root = manifest_dir();
        let mut files = Vec::new();
        for r in COGNITION_ROOTS {
            let d = root.join(r);
            if d.is_file() {
                files.push(d);
            } else if d.exists() {
                collect_rs(&d, &mut files);
            }
        }
        let mut violations = Vec::new();
        for f in &files {
            let rel = f
                .strip_prefix(&root)
                .unwrap_or(f)
                .to_string_lossy()
                .replace('\\', "/");
            if is_exempt(&rel) || rel.ends_with("src/core/laws.rs") {
                continue; // this guard names the banned types in prose
            }
            let Ok(text) = std::fs::read_to_string(f) else { continue };
            for (n, line) in text.lines().enumerate() {
                let code = code_of(line);
                for b in BANNED {
                    if code.contains(b) {
                        violations.push(format!("{rel}:{}: {}", n + 1, line.trim()));
                    }
                }
            }
        }
        assert!(
            violations.is_empty(),
            "Anti-Flattening Law (Law II) violated — maps in the cognition path \
             collapse relational geometry (docs/ANTI_FLATTENING_LAW.md). Move the \
             structure onto the retained blade/manifold, or below the sovereignty \
             boundary (core::chain / network). Offenders:\n{}",
            violations.join("\n")
        );
    }
}
